// ─────────────────────────────────────────────────────────────
// Verificador de Status HTTP dos Links
// Faz requisições HEAD em paralelo (lotes de 10)
// Coleta links com status problemático: 301, 302, 4xx, 5xx
// ─────────────────────────────────────────────────────────────

const item = $input.first().json;
const pageUrl = item.auditedUrl || '';
const rawLinks = item.allLinks || [];

function resolveUrl(href, base) {
  if (!href) return null;
  href = href.trim();
  if (href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:') || href.startsWith('javascript:')) return null;
  try {
    return new URL(href, base).href;
  } catch {
    return null;
  }
}

function problemLabel(status) {
  if (status === 301) return 'Redirecionamento permanente — atualize o href para a URL final';
  if (status === 302) return 'Redirecionamento temporário — verifique se deveria ser permanente';
  if (status === 404) return 'Página não encontrada — remova ou corrija o link';
  if (status === 410) return 'Recurso removido permanentemente — remova o link';
  if (status >= 400 && status < 500) return `Erro do cliente (${status}) — verifique e corrija o link`;
  if (status >= 500) return `Erro de servidor (${status}) — monitore e corrija`;
  return `Status inesperado (${status})`;
}

const seen = new Set();
const toCheck = [];
for (const href of rawLinks) {
  const abs = resolveUrl(href, pageUrl);
  if (!abs || seen.has(abs)) continue;
  seen.add(abs);
  toCheck.push(abs);
  if (toCheck.length >= 30) break;
}

const BATCH = 10;
const TIMEOUT_MS = 5000;
const issues = [];

async function checkUrl(url) {
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
    const resp = await fetch(url, {
      method: 'HEAD',
      redirect: 'manual',
      signal: ctrl.signal,
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)'
      }
    });
    clearTimeout(timer);
    const status = resp.status;
    if (status === 301 || status === 302 || status >= 400) {
      return { url, status, problem: problemLabel(status) };
    }
    return null;
  } catch (err) {
    if (err.name === 'AbortError') {
      return { url, status: 'TIMEOUT', problem: 'Requisição expirou — servidor lento ou URL inacessível' };
    }
    return null;
  }
}

for (let i = 0; i < toCheck.length; i += BATCH) {
  const batch = toCheck.slice(i, i + BATCH);
  const results = await Promise.all(batch.map(checkUrl));
  for (const r of results) {
    if (r) issues.push(r);
  }
}

return [{
  json: {
    ...item,
    linkStatusIssues: issues,
    linkStatusChecked: toCheck.length,
    linkStatusIssueCount: issues.length
  }
}];

const body = $input.first().json.body || {};
let url = String(body.url || '').trim();
if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url;
let valid = false;
try { new URL(url); valid = /^https?:\/\//i.test(url); } catch (e) {}
return [{ json: {
  valid,
  errors: valid ? [] : ['URL invalida ou ausente. Envie um JSON no formato {"url": "https://exemplo.com.br/pagina"}'],
  url
} }];
